st_date),marketplace ), rtos as ( SELECT LAST_DAY(DATE(original_return_request_date), MONTH) as return_month, date(original_return_request_date) as return_date, marketplace, COUNT(*) as total_rto_items_received_in_month, count(distinct reference_code) as rto_orders_received_in_month, sum(TOTAL_RETURNED_QUANTITY) as rto_quantity_received_in_month, FROM saadaa-wh.maplemonk.saadaa_returns_consolidated WHERE return_flag = 1 and return_request_type = \'RTO\' GROUP BY LAST_DAY(DATE(original_return_request_date), MONTH),date(original_return_request_date),marketplace ) SELECT o.month_first_date, o.marketplace, o.order_month, o.order_date, o.orders_for_the_month, o.total_order_items_for_the_month, o.total_order_quantity_for_the_month, o.total_returned_orders_for_orders_of_month, o.total_returned_items_for_orders_of_month, o.total_returned_quantity_for_orders_of_month, o.total_exchange_orders_for_orders_of_month, o.total_exchange_items_for_orders_of_month, o.total_exchange_quantity_for_orders_of_month, o.total_sales, r.total_returned_sales, r.return_date, r.total_returned_items_received_in_month, r.returned_orders_received_in_month, r.returned_quantity_received_in_month, e.total_exchange_items_received_in_month, e.exchange_orders_received_in_month, e.exchange_quantity_received_in_month, rt.total_rto_items_received_in_month, rt.rto_orders_received_in_month, rt.rto_quantity_received_in_month from orders o LEFT JOIN returns r ON r.return_date = o.order_date and r.marketplace = o.marketplace LEFT JOIN exchanges e ON e.return_date = o.order_date and e.marketplace = o.marketplace LEFT JOIN rtos rt ON rt.return_date = o.order_date and rt.marketplace = o.marketplace order by order_date desc;",
